FUNCTION_BLOCK FB
VAR_INPUT
    openBtn : BOOL;
    closeBtn : BOOL;
    openLimit : BOOL;
    closeLimit : BOOL;
    obstacle : BOOL;
END_VAR
VAR_OUTPUT
    motorUp : BOOL;
    motorDown : BOOL;
    errorFlag : BOOL;
END_VAR
VAR
    prevOpenBtn : BOOL := FALSE;
    prevCloseBtn : BOOL := FALSE;
    prevObstacle : BOOL := FALSE;
    prevMotorUp : BOOL := FALSE;
    prevMotorDown : BOOL := FALSE;
    prevErrorFlag : BOOL := FALSE;
    state : INT := 0;
END_VAR
VAR_TEMP
    openBtnRising : BOOL;
    closeBtnRising : BOOL;
    bothButtonsRising : BOOL;
END_VAR

openBtnRising := openBtn AND NOT prevOpenBtn;
closeBtnRising := closeBtn AND NOT prevCloseBtn;
bothButtonsRising := openBtnRising AND closeBtnRising;

prevOpenBtn := openBtn;
prevCloseBtn := closeBtn;
prevObstacle := obstacle;
prevMotorUp := motorUp;
prevMotorDown := motorDown;
prevErrorFlag := errorFlag;

motorUp := FALSE;
motorDown := FALSE;

IF obstacle THEN
    errorFlag := TRUE;
    state := 3;
ELSIF errorFlag THEN
    state := 3;
    IF !obstacle AND bothButtonsRising THEN
        errorFlag := FALSE;
        state := 0;
    END_IF
ELSE
    CASE state OF
        0:
            IF bothButtonsRising THEN
                errorFlag := FALSE;
            ELSIF openBtnRising AND !closeBtn AND !openLimit THEN
                motorUp := TRUE;
                state := 1;
            ELSIF closeBtnRising AND !openBtn AND !closeLimit THEN
                motorDown := TRUE;
                state := 2;
            END_IF
        1:
            IF openLimit THEN
                motorUp := FALSE;
                state := 0;
            ELSE
                motorUp := TRUE;
            END_IF
        2:
            IF closeLimit THEN
                motorDown := FALSE;
                state := 0;
            ELSE
                motorDown := TRUE;
            END_IF
        3:
    END_CASE
END_IF

END_FUNCTION_BLOCK
